WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_ms_ip_masses'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '与群众/服务对象', 'kp-ms-ip-masses', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "人际交往：与群众相处"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心法则：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "群众利益无小事。做群众的贴心人。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、高分破题"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "群众不配合你的工作怎么办？"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "绝对不能用公权力去压人！必须学会换位思考。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "第一步：反思自己是不是工作方法太生硬、政策宣传没到位。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "第二步：找群众里的“乡贤”、“老支书”、“意见领袖”帮忙做思想工作，用老百姓听得懂的话讲清利弊。解决他们的后顾之忧。"}]}]}$$ AS jsonb), NULL, '与群众/服务对象的核心考点与高分作答技巧。', category_node.id, CAST('["面试", "人际交往", "群众关系"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_ms_ip_masses", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
